function initFaq(){
  var nav=document.getElementById('faqNav'), body=document.getElementById('faqBody');
  if(!nav||!body) return;
  if(!body.children.length){
  nav.innerHTML=FAQ.map(function(g,i){ return '<button class="faq-cat-btn" type="button" data-i="'+i+'">'+esc(g.c)+' <em>'+g.q.length+'</em></button>'; }).join('');
  body.innerHTML=FAQ.map(function(g,i){
    return '<div class="faq-cat rv" id="faq-'+i+'"><h3>'+esc(g.c)+' <em>'+g.q.length+'</em></h3><div class="acc">'+
      g.q.map(function(f,k){
        return '<div class="acc-i'+(!i&&!k?' open':'')+'"><button class="acc-b" type="button">'+esc(f[0])+
          '<span class="chev"><svg width="11" height="7" viewBox="0 0 11 7" aria-hidden="true"><path d="M1 1l4.5 4.5L10 1" stroke="#43616F" stroke-width="1.5" fill="none" stroke-linecap="round"/></svg></span></button>'+
          '<div class="acc-p"><div><p>'+esc(f[1])+'</p></div></div></div>';
      }).join('')+'</div></div>';
  }).join('');
  }
  body.addEventListener('click',function(e){
    var b=e.target.closest('.acc-b'); if(!b) return;
    var it=b.closest('.acc-i'), open=it.classList.contains('open');
    b.closest('.acc').querySelectorAll('.acc-i').forEach(function(x){ x.classList.remove('open'); });
    if(!open) it.classList.add('open');
  });
  nav.addEventListener('click',function(e){
    var b=e.target.closest('.faq-cat-btn'); if(!b) return;
    var t=document.getElementById('faq-'+b.dataset.i);
    if(t) window.scrollTo({top:t.getBoundingClientRect().top+window.scrollY-100,behavior:REDUCE?'auto':'smooth'});
  });
  var fq=document.getElementById('faqQ'), none=document.getElementById('faqNone'), fc=document.getElementById('faqClear');
  function norm(s){ return s.toLowerCase().replace(/ё/g,'е'); }
  function search(){
    var q=norm((fq.value||'').trim());
    if(fc) fc.hidden=!q;
    nav.hidden=!!q;
    var found=0;
    body.querySelectorAll('.faq-cat').forEach(function(cat){
      var vis=0;
      cat.querySelectorAll('.acc-i').forEach(function(it){
        var m=!q||norm(it.textContent).indexOf(q)>-1;
        it.hidden=!m;
        if(m){ vis++; if(q) it.classList.add('open'); }
      });
      cat.hidden=!vis; found+=vis;
    });
    if(none) none.hidden=found>0;
  }
  if(fq) fq.addEventListener('input',search);
  if(fc) fc.addEventListener('click',function(){ fq.value=''; search(); fq.focus(); });
}

/* ============ НАБЛЮДАТЕЛИ ============ */
var io=new IntersectionObserver(function(es){
  es.forEach(function(e){
    if(!e.isIntersecting) return;
    var el=e.target;
    if(el.classList.contains('rv')) el.classList.add('in');
    if(el.classList.contains('cnt')){
      var to=+el.dataset.to, suf=el.dataset.suf||'', t0=performance.now();
      (function run(now){
        var k=Math.min(1,(now-t0)/1100), v=Math.round(to*(1-Math.pow(1-k,3)));
        el.textContent=v+(k===1?suf:'');
        if(k<1) requestAnimationFrame(run);
      })(t0);
    }
    if(el.classList.contains('ring')){
      var C=2*Math.PI*74;
      [['sOk',0,302],['sWarn',302,4],['sRisk',306,1]].forEach(function(a){
        var c=document.getElementById(a[0]); if(!c) return;
        c.style.transition='stroke-dasharray 1.2s cubic-bezier(.32,.72,0,1)';
        c.style.strokeDashoffset=(-C*a[1]/307);
        setTimeout(function(){ c.style.strokeDasharray=(C*a[2]/307)+' '+C; },60);
      });
    }
    io.unobserve(el);
  });
},{threshold:.16,rootMargin:'0px 0px -5% 0px'});
function observe(root){
  root.querySelectorAll('.rv:not(.in),.cnt,.ring').forEach(function(el){ io.observe(el); });
  setTimeout(function(){
    root.querySelectorAll('.rv:not(.in)').forEach(function(el){
      if(el.getBoundingClientRect().top<window.innerHeight+220) el.classList.add('in');
    });
  },800);
}

/* ============ ФОРМЫ ============ */
var MAIL=/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
function fields(f){ return [].slice.call(f.querySelectorAll('[data-req],[data-one]')).filter(function(el){ return !el.closest('[hidden]'); }); }
function filled(el){ if(el.type==='file') return el.files.length>0; if(el.type==='checkbox') return el.checked; return el.value.trim().length>0; }
function markBad(el,bad){ var w=el.closest('.field'); if(w) w.classList.toggle('bad',bad); }
function check(f,show){
  var ok=true, groups={};
  fields(f).forEach(function(el){
    if(el.dataset.one!==undefined){ (groups[el.dataset.one]=groups[el.dataset.one]||[]).push(el); return; }
    var bad=!filled(el)||(el.hasAttribute('data-mail')&&!MAIL.test(el.value.trim()));
    if(bad) ok=false;
    if(show) markBad(el,bad);
  });
  Object.keys(groups).forEach(function(g){
    var any=groups[g].some(filled);
    if(!any) ok=false;
    if(show){
      var w=groups[g][0].closest('.field');
      if(w) w.classList.toggle('bad',!any);
      groups[g].forEach(function(el){ if(el.type!=='checkbox') markBad(el,!any); });
    }
  });
  var ags=f.querySelectorAll('.agree input[data-agree]');
  for(var k=0;k<ags.length;k++){
    if(ags[k].closest('[hidden]')) continue;
    var lab=ags[k].closest('.agree');
    if(!ags[k].checked){ ok=false; if(show&&lab) lab.classList.add('bad'); }
    else if(lab) lab.classList.remove('bad');
  }
  return ok;
}
function refresh(f){ var b=f.querySelector('.submit'); if(b) b.classList.toggle('off',!check(f,false)); }
document.addEventListener('input',function(e){
  var f=e.target.closest('.mk-form'); if(!f) return;
  var w=e.target.closest('.field.bad'); if(w&&filled(e.target)) w.classList.remove('bad');
  refresh(f);
});
document.addEventListener('change',function(e){
  var f=e.target.closest('.mk-form'); if(!f) return;
  if(e.target.type==='file'){
    var box=e.target.closest('.filebox');
    if(box){ var n=e.target.files.length;
      box.querySelector('.fname').textContent=n?(n===1?e.target.files[0].name:'Выбрано файлов: '+n):'Выберите файлы';
      box.classList.toggle('has',n>0); }
  }
  if(e.target.name==='delivery'){
    var em=f.querySelector('[data-dl="mail"]'), tg=f.querySelector('[data-dl="tg"]');
    if(em&&tg){ var isTg=e.target.value==='tg'; em.hidden=isTg; tg.hidden=!isTg; }
  }
  if(e.target.closest('.agree')) e.target.closest('.agree').classList.remove('bad');
  refresh(f);
});

