  document.getElementById('fmT').textContent=title;
  var fs=document.getElementById('fmS'); fs.textContent=sub||''; fs.hidden=!sub;
  var needSurvey=(kind==='svc'&&['obj-fast','obj-deep','obj-full','deal','deal-all','land'].indexOf(key)>=0)
                 ||kind==='sub';
  var isDD=(kind==='svc'&&DD_SKUS[key]);
  SV=null; ddCur=null;
  document.getElementById('fmFields').innerHTML=isDD?ddFieldsHtml(key):(cfg.f.map(fieldHtml).join('')+deliveryHtml('f'));
  var mkKn=''; try{ mkKn=sessionStorage.getItem('mayak-kn')||''; }catch(x){}
  if(mkKn){ var mkKf=document.getElementById('fmFields').querySelector('[name="kad"]');
            if(mkKf&&!mkKf.value) mkKf.value=mkKn; }
  if(needSurvey) svState={};
  document.getElementById('fmSurvey').innerHTML=needSurvey?surveyHtml():'';
  if(isDD) ddRefreshSurvey(f);
  document.getElementById('fmAgrees').innerHTML=isDD?ddAgreesHtml():agreesHtml();
  var btn=f.querySelector('.submit');
  btn.innerHTML=(price?'Перейти к оплате':(kind==='sub'?'Оформить по абонементу':'Отправить заявку'))+ARR;
  pending={kind:kind,key:key,name:svcName,price:price,ptxt:ptxt};
  var s1 = (kind==='svc') ? step1Html(key) : (kind==='packsvc' ? packStep1Html(key) : '');
  document.getElementById('fmStep1').innerHTML=s1;
  var cr=document.getElementById('fmCr'); cr.hidden=!s1;
