/* ============ ОПЛАТА И ПОДТВЕРЖДЕНИЕ ============ */
function drawCheckout(){
  var box=document.getElementById('coSum'); if(!box) return;
  if(!order){ order={num:orderNum(),date:nowStr(),name:'Проверка объекта и продавца',price:4450,ptxt:'4 450 ₽',way:'на электронную почту',kind:'svc'}; saveOrder(); }
  box.innerHTML='<div><dt>Услуга</dt><dd>'+esc(order.name)+'</dd></div>'+
    '<div><dt>Номер заказа</dt><dd>'+order.num+'</dd></div>'+
    '<div><dt>Дата и время</dt><dd>'+order.date+'</dd></div>'+
    '<div><dt>Результат придёт</dt><dd>'+order.way+'</dd></div>'+
    '<div><dt>Итого</dt><dd>'+order.ptxt+'</dd></div>'+
    (order.consent?'<div><dt>Согласие на обработку данных</dt><dd>получено '+ddWhen(order.consent)+'</dd></div>':'');
}
function drawSuccess(){
  if(!document.getElementById('okNum')) return;
  if(!order){ order={num:orderNum(),date:nowStr(),name:'Заказ',price:0,ptxt:'—',way:'на электронную почту',kind:'svc'}; saveOrder(); }
  var q={}; try{ location.search.replace(/^\?/,'').split('&').forEach(function(p){ if(!p) return; var kv=p.split('='); q[decodeURIComponent(kv[0])]=(kv[1]&&decodeURIComponent(kv[1].replace(/\+/g,' ')))||''; }); }catch(x){}
  var st=(q.status||q.payment_status||'').toLowerCase();
  document.getElementById('okNum').textContent=order.num;
  document.getElementById('okDate').textContent=order.date;
  document.getElementById('okSum').textContent=order.price?order.ptxt:'без оплаты';
  var h=document.querySelector('.ok-hero h2');
  var way=document.getElementById('okWay');
  if(st==='canceled'||st==='cancelled'||st==='failed'){
    if(h) h.textContent='Оплата не завершена';
    if(way) way.textContent='Платёж отменён или не прошёл. Вы можете вернуться и оформить заказ ещё раз, либо написать на sales@mayak-legal.ru.';
    return;
  }
  if(st==='pending'||st==='waiting_for_capture'){
    if(h) h.textContent='Ожидаем подтверждение оплаты';
    if(way) way.textContent='Платёжный сервис ещё подтверждает платёж. Обычно это занимает несколько минут. Чек и результат придут '+order.way+'.';
    return;
  }
  if(way) way.textContent='«'+order.name+'». Результат работ придёт '+order.way+
    ' в срок, указанный для этой услуги. Чек формируется автоматически в момент оплаты и приходит на почту.';
  if(h) h.textContent=order.price?'Оплата прошла, заказ принят':'Заказ принят';
  goal(order.price?'payment_success':'order_success');
}
document.addEventListener('click',function(e){
  var payBtn=e.target.closest('#coPay');
  if(!payBtn) return;
  goal('pay_click');
  e.preventDefault();
  if(!order){ alert('Заказ не найден. Оформите заявку заново.'); return; }
  if(order.case_id&&order.dd){
    var prev=payBtn.innerHTML;
    payBtn.disabled=true; payBtn.textContent='Переходим к оплате…';
    ddPay(order.case_id).then(function(url){ location.href=url; }).catch(function(err){
      payBtn.disabled=false; payBtn.innerHTML=prev;
      alert((err&&err.message)||'Не удалось перейти к оплате');
    });
    return;
  }
  // Платные услуги без Estate API пока макет
  if(order.price>0){
    alert('Онлайн-оплата для этой услуги скоро будет доступна. Напишите на sales@mayak-legal.ru — оформим заказ вручную.');
    return;
  }
  go('success',true);
});

/* ============ ЛИЧНЫЙ КАБИНЕТ ============ */
function lkOpen(){
  var a=document.getElementById('lkAuth'), b=document.getElementById('lkBody');
  if(!a||!b) return;
  a.hidden=true; b.hidden=false; observe(b);
}
function lkClose(){
  var a=document.getElementById('lkAuth'), b=document.getElementById('lkBody');
  if(!a||!b) return;
  a.hidden=false; b.hidden=true;
  var f=document.getElementById('formAuth'); if(f) f.classList.remove('sent');
}
document.addEventListener('click',function(e){
  var t=e.target.closest('.lk-tab');
  if(t){
    document.querySelectorAll('.lk-tab').forEach(function(x){ x.classList.toggle('on',x===t); });
    document.querySelectorAll('.lk-pane').forEach(function(p){ p.hidden=(p.dataset.pane!==t.dataset.tab); });
    var pane=document.querySelector('.lk-pane[data-pane="'+t.dataset.tab+'"]'); if(pane) observe(pane);
    return;
  }
  if(e.target.closest('#lkOut')){ lkClose(); return; }
  var aw=e.target.closest('[data-auth]');
  if(aw){ lkOpen(); return; }
  var lk=e.target.closest('[data-lk]');
  if(lk){
    var m=document.getElementById('docModal'); if(!m) return;
    var res=lk.dataset.lk==='res';
    document.getElementById('dmT').textContent=res?'Результат работ':'Чек';
    document.getElementById('dmB').innerHTML=res
      ? '<p>В рабочей версии здесь открывается файл результата: отчёт в PDF, договор в DOCX или заключение юриста — с возможностью скачать и переслать.</p><p class="small">Файлы хранятся в кабинете 90 дней после отправки результата.</p>'
      : '<p>В рабочей версии здесь открывается чек из приложения «Мой налог» Федеральной налоговой службы — его можно скачать или переслать.</p><p class="small">Чек также приходит на указанную Вами почту в момент оплаты.</p>';
    openModal(m);
  }
});

/* ============ ЯНДЕКС МЕТРИКА (только после согласия на аналитику) ============ */
var METRIKA_ID='113527974';  /* счётчик «Маяк» в metrika.yandex.ru; при согласии код в <head> страницы загружает его раньше */
function loadMetrika(){
  if(!METRIKA_ID) return;
  document.querySelectorAll('input,textarea').forEach(function(el){ el.classList.add('ym-disable-keys'); });
  if(window.ym) return;  /* уже загружена кодом в <head> */
  window.dataLayer=window.dataLayer||[];
  (function(m,e,t,r,i,k,a){m[i]=m[i]||function(){(m[i].a=m[i].a||[]).push(arguments)};m[i].l=1*new Date();
   for(var j=0;j<document.scripts.length;j++){if(document.scripts[j].src===r){return;}}
   k=e.createElement(t);a=e.getElementsByTagName(t)[0];k.async=1;k.src=r;a.parentNode.insertBefore(k,a);})
   (window,document,'script','https://mc.yandex.ru/metrika/tag.js?id='+METRIKA_ID,'ym');
  window.ym(+METRIKA_ID,'init',{ssr:true,webvisor:true,clickmap:true,ecommerce:'dataLayer',referrer:document.referrer,url:location.href,accurateTrackBounce:true,trackLinks:true});
}
function goal(name){ try{ if(window.ym&&METRIKA_ID) window.ym(+METRIKA_ID,'reachGoal',name); }catch(x){} }

