(function(){
  var isl=document.querySelector('.head .island'), nav=isl&&isl.querySelector('.nav'); if(!nav) return;
  if(!nav.id) nav.id='mainNav';
  var b=document.createElement('button');
  b.type='button'; b.className='burger'; b.setAttribute('aria-controls',nav.id); b.setAttribute('aria-expanded','false'); b.setAttribute('aria-label','Открыть меню');
  b.innerHTML='<span></span><span></span><span></span>';
  isl.appendChild(b);
  function set(o){ isl.classList.toggle('open',o); b.setAttribute('aria-expanded',o?'true':'false'); b.setAttribute('aria-label',o?'Закрыть меню':'Открыть меню'); }
  b.addEventListener('click',function(){ set(!isl.classList.contains('open')); });
  nav.addEventListener('click',function(e){ if(e.target.closest('a')) set(false); });
  document.addEventListener('keydown',function(e){ if(e.key==='Escape'&&isl.classList.contains('open')){ set(false); b.focus(); } });
  document.addEventListener('click',function(e){ if(isl.classList.contains('open')&&!isl.contains(e.target)) set(false); });
  window.addEventListener('resize',function(){ if(window.innerWidth>1040) set(false); });
})();

